	err := installOrUpgradeWithLoader(
		context.Background(),
		actionCfg,
		loader,
		generated,
		"0.0.0",
		"nvidia-network-operator",
		testLaunchKitVersion,
		true, // overwriteExisting
		30*time.Second,
